package ru.folio.notes;

import java.awt.*;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.*;
import javax.imageio.ImageIO;

public final class ShapeAssistTests {
    static int assertions;static Random random=new Random(740);
    static void check(boolean yes,String label){if(!yes)throw new AssertionError(label);assertions++;}
    static Ink.Stroke polygon(float[][] vertices,float noise,float angle){Ink.Stroke s=new Ink.Stroke();s.color=0xff7971be;s.width=4;float c=(float)Math.cos(angle),sn=(float)Math.sin(angle);for(int edge=0;edge<vertices.length-1;edge++)for(int i=0;i<30;i++){float t=i/30f,x=vertices[edge][0]+(vertices[edge+1][0]-vertices[edge][0])*t,y=vertices[edge][1]+(vertices[edge+1][1]-vertices[edge][1])*t;x+=(random.nextFloat()-.5f)*noise;y+=(random.nextFloat()-.5f)*noise;s.points.add(new Ink.Pt(300+x*c-y*sn,260+x*sn+y*c,.6f,.3f,.2f));}float[] end=vertices[vertices.length-1];s.points.add(new Ink.Pt(300+end[0]*c-end[1]*sn,260+end[0]*sn+end[1]*c,1,0,0));return s;}
    static Ink.Stroke ellipse(float rx,float ry,float angle,float noise,float sweep){Ink.Stroke s=new Ink.Stroke();s.width=4;s.color=0xff7971be;for(int i=0;i<=180;i++){double t=sweep*i/180;float x=rx*(float)Math.cos(t)+(random.nextFloat()-.5f)*noise,y=ry*(float)Math.sin(t)+(random.nextFloat()-.5f)*noise;s.points.add(new Ink.Pt(300+x*(float)Math.cos(angle)-y*(float)Math.sin(angle),260+x*(float)Math.sin(angle)+y*(float)Math.cos(angle),1,0,0));}return s;}
    static void lineAndTools(){Ink.Stroke line=polygon(new float[][]{{-120,0},{120,0}},3,.05f);ShapeRecognizer.Result r=ShapeRecognizer.recognize(line,1);check(r!=null&&r.kind.equals("line"),"rough line recognized");check(Math.abs(r.stroke.points.get(0).y-r.stroke.points.get(r.stroke.points.size()-1).y)<.001,"near-horizontal line aligns");check(r.stroke.color==line.color&&r.stroke.width==line.width&&r.stroke.action.equals(line.action),"style and undo action retained");Ink.Stroke square=new Ink.Stroke();square.tool="rect";square.points.add(new Ink.Pt(10,20,1,0,0));square.points.add(new Ink.Pt(210,212,1,0,0));Ink.Stroke corrected=ShapeRecognizer.alignTool(square);check(Math.abs((corrected.points.get(1).x-10)-(corrected.points.get(1).y-20))<.001,"near-square shape tool aligns");Ink.Stroke arrow=line.copy();arrow.tool="arrow";arrow.points.clear();arrow.points.add(new Ink.Pt(0,0,1,0,0));arrow.points.add(new Ink.Pt(200,7,1,0,0));check(ShapeRecognizer.alignTool(arrow).points.size()==5,"arrow keeps arrowhead after alignment");System.out.println("PASS held line, axis snap, square assistance, style and arrowheads");}
    static void closed(){int count=0;for(int noise:new int[]{3,6,10})for(int rotation=0;rotation<10;rotation++){float angle=rotation*.21f;Ink.Stroke[] strokes={polygon(new float[][]{{-110,-65},{110,-65},{110,65},{-110,65},{-110,-65}},noise,angle),polygon(new float[][]{{0,-110},{110,80},{-90,80},{0,-110}},noise,angle),ellipse(100,100,angle,noise,(float)Math.PI*2),ellipse(140,65,angle,noise,(float)Math.PI*2)};String[] kinds={"rectangle","triangle","circle","ellipse"};for(int i=0;i<strokes.length;i++){ShapeRecognizer.Result r=ShapeRecognizer.recognize(strokes[i],1);check(r!=null,"closed shape found "+kinds[i]+" at "+angle);check(r.kind.equals(kinds[i]),"shape kind "+kinds[i]+" at "+angle+" was "+r.kind);Ink.Pt a=r.stroke.points.get(0),z=r.stroke.points.get(r.stroke.points.size()-1);check(Ink.dist(a.x,a.y,z.x,z.y)<.001,"fitted contour closes");for(float t:new float[]{0,.1f,.5f,.9f,1}){Ink.Stroke preview=r.frame(t);check(preview.action.equals(strokes[i].action),"morph keeps action group");for(Ink.Pt p:preview.points)check(Float.isFinite(p.x)&&Float.isFinite(p.y),"finite shape morph");}count++;}}
        System.out.println("PASS "+count+" rotated and noisy rectangles, triangles, circles and ellipses");}
    static void negative(){Ink.Stroke arc=ellipse(100,100,0,1,(float)Math.PI*1.35f);check(ShapeRecognizer.recognize(arc,1)==null,"open arc remains freehand");Ink.Stroke zigzag=polygon(new float[][]{{-120,-60},{-60,60},{0,-60},{60,60},{120,-60}},2,0);check(ShapeRecognizer.recognize(zigzag,1)==null,"writing zigzag remains freehand");Ink.Stroke concave=polygon(new float[][]{{-100,-70},{100,-70},{100,-10},{-30,-10},{-30,70},{-100,70},{-100,-70}},1,0);ShapeRecognizer.Result concaveResult=ShapeRecognizer.recognize(concave,1);check(concaveResult!=null&&concaveResult.kind.equals("polygon"),"concave L is preserved as a non-convex polygon");Ink.Stroke repeated=ellipse(100,100,0,1,(float)Math.PI*4);check(ShapeRecognizer.recognize(repeated,1)==null,"double loop is not replaced");check(ShapeRecognizer.recognize(ellipse(9,9,0,1,(float)Math.PI*2),1)==null,"small handwriting loop stays unchanged");Ink.Stroke laser=ellipse(100,100,0,1,(float)Math.PI*2);laser.tool="laser";check(ShapeRecognizer.recognize(laser,1)==null,"laser never enters shape recognition");System.out.println("PASS open writing, repeated loops and small marks remain freehand; concave polygon keeps its notch");}
    static void spring(){SmoothSpring s=new SmoothSpring(0,24);s.target(1);for(int i=0;i<15;i++)s.step(1/120f);float value=s.value,velocity=s.velocity;s.target(0);check(s.value==value&&s.velocity==velocity,"retarget preserves position and velocity");check(Float.isFinite(s.velocity),"finite spring velocity");for(int i=0;i<300;i++){s.target(i%13<6?1:0);s.step(1/144f);check(Float.isFinite(s.value)&&Float.isFinite(s.velocity),"rapid switch remains finite");check(s.value>-.3&&s.value<1.3,"rapid switch remains bounded");}s.target(1);for(int i=0;i<240;i++)s.step(1/120f);check(s.value==1&&s.velocity==0,"spring settles exactly and stops");SmoothSpring a=new SmoothSpring(0,24),b=new SmoothSpring(0,24);a.target(500);b.target(500);for(int i=0;i<30;i++)a.step(1/60f);for(int i=0;i<72;i++)b.step(1/144f);check(Math.abs(a.value-b.value)<.002,"same motion at 60 and 144 Hz");s.snap(0);s.target(1);s.step(10);check(s.value>=0&&s.value<=1,"long frame does not explode");System.out.println("PASS spring continuity, interruption, rapid retargeting and 60/144 Hz consistency");}
    static void driver(){android.view.View view=new android.view.View();SmoothSpring value=new SmoothSpring(0,24);int[] updates={0},ends={0};SpringDriver driver=new SpringDriver(view,()->updates[0]++,value);driver.settled=()->ends[0]++;android.view.Choreographer clock=android.view.Choreographer.getInstance();driver.to(true,100);clock.advance(1000000000L);clock.advance(1016000000L);float x=value.value,v=value.velocity;check(driver.running&&x>0&&x<100,"native driver emits intermediate positions");driver.to(true,20);check(value.value==x&&value.velocity==v&&clock.pending()==1,"retarget keeps velocity and one callback");for(int i=2;i<150;i++)clock.advance(1000000000L+i*16000000L);check(!driver.running&&clock.pending()==0&&value.value==20&&ends[0]==1,"driver settles and releases callbacks");driver.to(true,20);check(ends[0]==2&&!driver.running,"already-settled close still completes");driver.to(true,40);view.detach();check(!driver.running&&clock.pending()==0,"detached panel removes frame callbacks");driver.to(false,50);check(value.value==50&&clock.pending()==0,"disabled motion applies immediately");System.out.println("PASS production spring driver retargeting, completion, disabled motion and detach cleanup");}
    static void draw(Graphics2D g,Ink.Stroke s,int color){g.setColor(new Color(color));g.setStroke(new BasicStroke(s.width,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));Path2D path=new Path2D.Float();if(!s.points.isEmpty()){path.moveTo(s.points.get(0).x,s.points.get(0).y);for(Ink.Pt p:s.points)path.lineTo(p.x,p.y);g.draw(path);}}
    static void visual(File output)throws Exception{BufferedImage image=new BufferedImage(1100,700,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(0xf5f2e9));g.fillRect(0,0,1100,700);g.setColor(new Color(0x383c4a));g.setFont(new Font("SansSerif",Font.BOLD,23));g.drawString("Folio / удержание пера выравнивает фигуру",35,40);Ink.Stroke[] examples={polygon(new float[][]{{-110,-65},{110,-65},{110,65},{-110,65},{-110,-65}},10,.04f),ellipse(110,102,0,7,(float)Math.PI*2),polygon(new float[][]{{0,-90},{110,80},{-100,80},{0,-90}},8,.07f),polygon(new float[][]{{-120,0},{120,0}},7,.04f)};for(int i=0;i<4;i++){Graphics2D cell=(Graphics2D)g.create();cell.translate(i%2*520-30,i/2*300-70);draw(cell,examples[i],0xc3bbc9);ShapeRecognizer.Result r=ShapeRecognizer.recognize(examples[i],1);if(r!=null)draw(cell,r.stroke,0x7971be);cell.dispose();}g.dispose();ImageIO.write(image,"png",output);}
    public static void main(String[] args)throws Exception{lineAndTools();closed();negative();spring();driver();visual(new File(args[0]));System.out.println("PASS: "+assertions+" shape and toolbar motion assertions");}
}
